&lt;b&gt;Langues&lt;/b&gt; commun, orque
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; armes famili&#232;res
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement de combat&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Parchemins-Magiques.html&quot; title=&quot;Les parchemins magiques&quot;&gt;parchemin&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Cacophonie.html&quot; title=&quot;Cacophonie&quot;&gt;cacophonie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Parchemins-Magiques.html&quot; title=&quot;Les parchemins magiques&quot;&gt;parchemin&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-Ii.html&quot; title=&quot;Convocation de monstres II&quot;&gt;convocation de monstres II&lt;/a&gt;&lt;/i&gt; ; &lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cuirasse-(Armure).html&quot; title=&quot;Cuirasse&quot;&gt;cuirasse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Hache-Darmes-(Arme).html&quot; title=&quot;Hache d&amp;#39;armes&quot;&gt;hache de guerre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Javeline-(Arme).html&quot; title=&quot;Javeline&quot;&gt;javelines&lt;/a&gt; (4), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-R&#233;sistance.html&quot; title=&quot;Cape de r&#233;sistance&quot;&gt;cape de r&#233;sistance +1&lt;/a&gt;&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-(Objet).html&quot; title=&quot;Symbole sacr&#233;&quot;&gt;symbole sacr&#233; en bois&lt;/a&gt;, 135 po
